## Как это выглядит для пользователя

На экране истории есть кнопка «Экспорт в CSV». Она открывает стандартное меню «Поделиться», где можно сохранить файл в «Файлы», отправить по почте, в мессенджер или по AirDrop. Файл называется, например, `История чтения 2026-10-28.csv` и сразу открывается в Excel и Numbers: колонки разложены правильно, кириллица читается, даты распознаются как даты.

## Файл 1. `ReadingHistoryCSV.swift`: сборка CSV

Здесь используется только Foundation, поэтому файл можно положить в логический пакет.

```swift
import Foundation

/// Одна строка экспорта. Простая копия данных сессии, чтобы экспорт
/// можно было безопасно собирать в фоне (Swift 6, строгая конкурентность).
public struct ReadingHistoryRow: Sendable, Equatable {
    public var startedAt: Date
    public var duration: TimeInterval
    public var timeZoneIdentifier: String
    public var bookTitle: String
    public var bookAuthor: String

    public init(
        startedAt: Date,
        duration: TimeInterval,
        timeZoneIdentifier: String,
        bookTitle: String,
        bookAuthor: String
    ) {
        self.startedAt = startedAt
        self.duration = duration
        self.timeZoneIdentifier = timeZoneIdentifier
        self.bookTitle = bookTitle
        self.bookAuthor = bookAuthor
    }
}

public enum ReadingHistoryCSV {
    /// Excel делит колонки по разделителю списка из региональных настроек:
    /// там, где дробная часть отделяется запятой (Россия, Европа), это «;».
    public enum Separator: String, Sendable {
        case comma = ","
        case semicolon = ";"

        public static func matching(_ locale: Locale) -> Separator {
            locale.decimalSeparator == "," ? .semicolon : .comma
        }
    }

    /// Готовое содержимое файла: UTF-8 с BOM, иначе Excel покажет кириллицу «кракозябрами».
    public static func data(for rows: [ReadingHistoryRow], separator: Separator) -> Data {
        var data = Data([0xEF, 0xBB, 0xBF])
        data.append(Data(text(for: rows, separator: separator).utf8))
        return data
    }

    public static func text(for rows: [ReadingHistoryRow], separator: Separator) -> String {
        let header = ["Начало", "Длительность (мин)", "Книга", "Автор"]
        var lines = [line(header, separator)]
        for row in rows.sorted(by: { $0.startedAt < $1.startedAt }) {
            lines.append(line([
                startText(row.startedAt, timeZoneIdentifier: row.timeZoneIdentifier),
                String(minutes(row.duration)),
                row.bookTitle,
                row.bookAuthor,
            ], separator))
        }
        // RFC 4180: строки завершаются CRLF.
        return lines.joined(separator: "\r\n") + "\r\n"
    }

    static func line(_ fields: [String], _ separator: Separator) -> String {
        fields.map { escape($0, separator) }.joined(separator: separator.rawValue)
    }

    /// Экранирование по RFC 4180 плюс защита от формул.
    static func escape(_ field: String, _ separator: Separator) -> String {
        var value = field
        // Excel выполняет ячейку, начинающуюся с = + - @, как формулу,
        // даже если она в кавычках. Апостроф превращает её в обычный текст.
        if let first = value.unicodeScalars.first, "=+-@\t\r".unicodeScalars.contains(first) {
            value = "'" + value
        }
        let separatorCharacter = Character(separator.rawValue)
        let needsQuotes = value.contains { $0 == "\"" || $0 == separatorCharacter || $0.isNewline }
        guard needsQuotes else { return value }
        return "\"" + value.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }

    /// Местное время того места, где человек читал: «2026-10-28 21:05».
    /// Такой формат Excel и Numbers распознают как дату и время при любом языке системы.
    static func startText(_ date: Date, timeZoneIdentifier: String) -> String {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: timeZoneIdentifier) ?? .current
        let parts = calendar.dateComponents([.year, .month, .day, .hour, .minute], from: date)
        return String(
            format: "%04ld-%02ld-%02ld %02ld:%02ld",
            parts.year ?? 0, parts.month ?? 0, parts.day ?? 0, parts.hour ?? 0, parts.minute ?? 0
        )
    }

    /// Целые минуты с округлением до ближайшего; мусорные значения дают 0, а не падение.
    static func minutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int(min(duration / 60, 1_000_000).rounded())
    }
}
```

## Файл 2. `ReadingHistoryExport.swift`: файл для ShareLink

Этот файл кладётся в таргет приложения.

```swift
import CoreTransferable
import Foundation
import UniformTypeIdentifiers

/// То, что отдаётся в ShareLink. Файл создаётся только когда пользователь
/// действительно выбрал, куда отправить, а не при каждой отрисовке экрана.
struct ReadingHistoryExport: Transferable, Sendable {
    let rows: [ReadingHistoryRow]
    let separator: ReadingHistoryCSV.Separator
    let fileName: String

    static var transferRepresentation: some TransferRepresentation {
        FileRepresentation(exportedContentType: .commaSeparatedText) { export in
            // Отдельная папка на каждый экспорт, чтобы файлы с одинаковым именем не мешали друг другу.
            let folder = FileManager.default.temporaryDirectory
                .appendingPathComponent(UUID().uuidString, isDirectory: true)
            try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
            let url = folder.appendingPathComponent(export.fileName)
            try ReadingHistoryCSV.data(for: export.rows, separator: export.separator)
                .write(to: url, options: .atomic)
            return SentTransferredFile(url)
        }
    }
}

extension ReadingHistoryExport {
    init(sessions: [ReadingSession], now: Date = .now, locale: Locale = .current) {
        rows = sessions.map {
            ReadingHistoryRow(
                startedAt: $0.startedAt,
                duration: $0.duration,
                timeZoneIdentifier: $0.timeZoneIdentifier,
                bookTitle: $0.bookTitle,
                bookAuthor: $0.bookAuthor
            )
        }
        separator = .matching(locale)
        let day = now.formatted(Date.ISO8601FormatStyle(timeZone: .current).year().month().day())
        fileName = "История чтения \(day).csv"
    }
}
```

