import Foundation

/// Builds a reading-history CSV that opens correctly in Excel and Numbers.
public enum ReadingHistoryCSV {
    public struct Row: Sendable, Equatable {
        public var startedAt: Date
        public var duration: TimeInterval
        public var timeZoneIdentifier: String
        public var bookTitle: String
        public var bookAuthor: String

        public init(
            startedAt: Date,
            duration: TimeInterval,
            timeZoneIdentifier: String,
            bookTitle: String,
            bookAuthor: String
        ) {
            self.startedAt = startedAt
            self.duration = duration
            self.timeZoneIdentifier = timeZoneIdentifier
            self.bookTitle = bookTitle
            self.bookAuthor = bookAuthor
        }
    }

    public enum Separator: String, Sendable {
        case comma = ","
        case semicolon = ";"

        /// Excel uses ";" as the list separator wherever "," is the decimal separator (Russia, most of Europe).
        public static func matching(_ locale: Locale) -> Separator {
            locale.decimalSeparator == "," ? .semicolon : .comma
        }
    }

    public static let header = ["Начало", "Длительность (мин)", "Название", "Автор"]

    /// UTF-8 with BOM: without it Excel shows Cyrillic as garbage.
    public static func data(rows: [Row], separator: Separator) -> Data {
        var data = Data([0xEF, 0xBB, 0xBF])
        data.append(Data(text(rows: rows, separator: separator).utf8))
        return data
    }

    public static func text(rows: [Row], separator: Separator) -> String {
        var lines = [line(header, separator)]
        for row in rows.sorted(by: { $0.startedAt < $1.startedAt }) {
            lines.append(line([
                localDateTime(row.startedAt, timeZoneIdentifier: row.timeZoneIdentifier),
                String(minutes(row.duration)),
                neutralizingFormula(row.bookTitle),
                neutralizingFormula(row.bookAuthor),
            ], separator))
        }
        // RFC 4180: CRLF line endings, including after the last record.
        return lines.joined(separator: "\r\n") + "\r\n"
    }

    // MARK: - Fields

    /// Local wall-clock time where the session happened, in a format both apps recognize as a date.
    static func localDateTime(_ date: Date, timeZoneIdentifier: String) -> String {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: timeZoneIdentifier) ?? .current
        let c = calendar.dateComponents([.year, .month, .day, .hour, .minute], from: date)
        return "\(pad(c.year, 4))-\(pad(c.month, 2))-\(pad(c.day, 2)) \(pad(c.hour, 2)):\(pad(c.minute, 2))"
    }

    /// Whole minutes, rounded to nearest; an integer avoids decimal-separator mismatches between locales.
    static func minutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int(min((duration / 60).rounded(), 1_000_000_000))
    }

    /// A cell starting with = + - @ is run as a formula by Excel; a leading apostrophe keeps it plain text.
    static func neutralizingFormula(_ text: String) -> String {
        guard let first = text.unicodeScalars.first, "=+-@\t\r".unicodeScalars.contains(first) else {
            return text
        }
        return "'" + text
    }

    // MARK: - Encoding

    static func line(_ fields: [String], _ separator: Separator) -> String {
        fields.map { escaped($0, separator) }.joined(separator: separator.rawValue)
    }

    /// Works on Unicode scalars, not Characters: in Swift "\r\n" is a single Character
    /// and a quote followed by a combining mark is too, so Character-based checks miss them.
    static func escaped(_ field: String, _ separator: Separator) -> String {
        let special = Set(("\"\r\n" + separator.rawValue).unicodeScalars)
        let needsQuotes = field.unicodeScalars.contains { special.contains($0) }
            || field.first?.isWhitespace == true
            || field.last?.isWhitespace == true
        guard needsQuotes else { return field }

        var result = String.UnicodeScalarView()
        result.append("\"")
        for scalar in field.unicodeScalars {
            if scalar == "\"" { result.append("\"") }
            result.append(scalar)
        }
        result.append("\"")
        return String(result)
    }

    private static func pad(_ value: Int?, _ width: Int) -> String {
        let digits = String(value ?? 0)
        return String(repeating: "0", count: max(0, width - digits.count)) + digits
    }
